B.Qv=new A.d6("palpitations","Heart palpitations","\u062e\u0641\u0642\u0627\u0646 \u0627\u0644\u0642\u0644\u0628","\u2764\ufe0f",!0,3,"Irregular heartbeat or chest discomfort \u2014 contact your care team immediately.",null)
B.bY=new A.d6("sleep","Sleep quality","\u062c\u0648\u062f\u0629 \u0627\u0644\u0646\u0648\u0645","\ud83d\ude34",!1,4,null,"A consistent bedtime routine helps. Avoid screens 30 minutes before sleep.")
B.Qw=new A.d6("joint_pain","Joint / muscle pain","\u0622\u0644\u0627\u0645 \u0627\u0644\u0645\u0641\u0627\u0635\u0644","\ud83e\uddb4",!1,4,null,"Peaks 2\u20134 days after Taxol. Gentle warm compresses and light movement can help.")
B.Qx=new A.d6("skin_nails","Skin / nail changes","\u062a\u063a\u064a\u0631\u0627\u062a \u0627\u0644\u062c\u0644\u062f \u0648\u0627\u0644\u0623\u0638\u0627\u0641\u0631","\ud83d\udc85",!1,4,null,"Keep nails clean and short. Moisturise hands daily. Avoid cutting cuticles.")
B.d9=new A.d6("breathlessness","Breathlessness","\u0636\u064a\u0642 \u0627\u0644\u062a\u0646\u0641\u0633","\ud83e\udec1",!0,4,"Breathlessness at rest or with light activity \u2014 contact your care team today.",null)
B.A0=new A.d6("vomiting","Vomiting","\u0642\u064a\u0621","\ud83e\udd22",!0,5,"More than 2\u20133 episodes \u2014 contact your care team. You may need anti-nausea medication adjustment.",null)
B.bG=new A.d6("mood","Mood / anxiety","\u0627\u0644\u0645\u0632\u0627\u062c / \u0627\u0644\u0642\u0644\u0642","\ud83d\udc9c",!1,4,null,"What you're feeling is a normal response to treatment. Talking about it helps.")
B.cQ=new A.d6("nausea","Nausea","\u063a\u062b\u064a\u0627\u0646","\ud83c\udf0a",!1,4,null,"Small frequent meals every 2\u20133 hours. Cold or room-temperature foods are easier to tolerate.")
B.bf=new A.d6("fever","Fever / Temperature","\u062d\u0645\u0649 / \u062d\u0631\u0627\u0631\u0629","\ud83c\udf21\ufe0f",!0,3,"Fever above 38\xb0C (100.4\xb0F) during chemotherapy \u2014 call your care team immediately, day or night. Do not wait.",null)
B.m6=new A.d6("neuropathy","Tingling / numbness","\u062a\u0646\u0645\u064a\u0644","\ud83e\udd32",!0,7,"Severe tingling or numbness \u2014 report to your care team at next visit or call if it affects walking.","Hands and feet tingling is common with Taxol. Tell your team \u2014 dose adjustment may help.")
